 * Parses the election format described in the task: a `candidates` line
 * declaring the field, followed by any number of `ballot` lines. Throws a
 * `ParseError` carrying the offending line number for any malformed input.
 */

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        fail('expected candidates <name>...', lineNumber)
      }
      const names = tokens.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!NAME.test(name)) fail(`invalid candidate name ${name}`, lineNumber)
        if (seen.has(name)) fail(`candidate ${name} is declared twice`, lineNumber)
        seen.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT.test(countText)) fail('count must be a positive integer', lineNumber)
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidates.includes(name)) fail(`unknown candidate ${name}`, lineNumber)
        if (seen.has(name)) fail(`candidate ${name} is repeated`, lineNumber)
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (candidates === null) fail('no candidates', null)

  return { candidates, ballots }
}
"}

