{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-Azil6U/src/count.js","content":"/**
 * Runs the instant-runoff count described in the task: each round tallies
 * every ballot for its most preferred continuing candidate, then either
 * declares a winner, declares no winner, or eliminates one candidate and
 * continues.
 */

/**
 * Picks which of the tied-for-fewest candidates to eliminate. `tied` is the
 * set of candidate names with the fewest votes in the current round; `history`
 * is the list of per-round vote tallies (one Map per round counted so far,
 * this round included) for every candidate still continuing.
 */
function chooseElimination(tied, history) {
  let candidates = tied
  while (candidates.length > 1) {
    let narrowed = null
    for (const roundVotes of history) {
      const values = candidates.map((name) => roundVotes.get(name))
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        const min = Math.min(...values)
        narrowed = candidates.filter((name) => roundVotes.get(name) === min)
        break
      }
    }
    if (narrowed === null) break
    candidates = narrowed
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.slice().sort().reverse()[0]
}

export function runElection({ candidates, ballots }) {
  let continuing = candidates.slice()
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.includes(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = continuing.reduce((sum, name) => sum + votes.get(name), 0)

    const ordered = continuing.slice().sort((a, b) => {
      const diff = votes.get(b) - votes.get(a)
      return diff !== 0 ? diff : a < b ? -1 : a > b ? 1 : 0
    })

    if (activeTotal === 0) {
      rounds.push({ ordered, votes, exhausted, eliminated: null })
      break
    }

    const majority = continuing.find((name) => votes.get(name) * 2 > activeTotal)
    if (majority !== undefined) {
      rounds.push({ ordered, votes, exhausted, eliminated: null })
      winner = majority
      break
    }

    const fewest = Math.min(...continuing.map((name) => votes.get(name)))
    const tied = continuing.filter((name) => votes.get(name) === fewest)
    const eliminated = chooseElimination(tied, history)

    rounds.push({ ordered, votes, exhausted, eliminated })
    continuing = continuing.filter((name) => name !== eliminated)
  }

  return { rounds, winner }
}
"}

